            LogCurve::AppleLog2 => &[CameraGamut::AppleWideGamut],
            LogCurve::Slog3 => &[CameraGamut::SGamut3Cine, CameraGamut::SGamut3],
            LogCurve::Vlog => &[CameraGamut::VGamut],
